package com.thangit.boardinghouse.service;

import com.thangit.boardinghouse.common.exception.AuthException;
import com.thangit.boardinghouse.domain.auth.RoleCode;
import com.thangit.boardinghouse.security.AuthenticatedUser;
import com.thangit.boardinghouse.dto.request.invoice.AdminInvoiceRequests.*;
import jakarta.validation.constraints.*;
import java.math.*;
import java.time.*;
import java.time.temporal.ChronoUnit;
import java.util.*;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import org.springframework.http.HttpStatus;
import org.springframework.jdbc.core.simple.JdbcClient;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/** Single source of monthly calculations. All amounts are snapshots, never listing prices. */
@Service
public class MonthlyBillingService {
    public record Reading(@NotNull LocalDate period,@NotNull @Min(0) Long version,
        @DecimalMin("0") BigDecimal electricity,@DecimalMin("0") BigDecimal water,
        @NotBlank @Size(max=500) String reference,@NotBlank @Size(max=1000) String reason,boolean confirmWarnings) {}
    public record Replacement(@NotNull LocalDate period,@NotNull @Min(0) Long version,
        @NotBlank @Pattern(regexp="ELECTRICITY|WATER") String type,@NotBlank @Size(max=50) String code,
        @NotNull @DecimalMin("0") BigDecimal removedReading,@NotNull @DecimalMin("0") BigDecimal installedReading,
        @NotBlank @Size(max=500) String reference,@NotBlank @Size(max=1000) String reason) {}
    public record Rate(@NotBlank @Pattern(regexp="ELECTRICITY|WATER|RENT") String code,@NotNull LocalDate effectiveDate,
        @NotNull @DecimalMin("0") BigDecimal unitPrice,@NotBlank @Size(max=500) String reference,@NotBlank @Size(max=1000) String reason) {}
    public record ServiceRule(@NotBlank @Size(max=30) String code,@NotBlank @Size(max=100) String name,
        @NotBlank @Pattern(regexp="FIXED|PER_PERSON|QUANTITY|USAGE|ONCE") String method,
        @NotBlank @Size(max=30) String unit,@NotNull @DecimalMin("0") BigDecimal unitPrice,
        @DecimalMin("0") BigDecimal quantity,@NotNull LocalDate effectiveDate,LocalDate endDate,boolean prorate,
        @NotBlank @Size(max=1000) String reason) {}
    public record Usage(@NotNull LocalDate period,@NotNull @DecimalMin("0") BigDecimal quantity,@NotBlank @Size(max=500) String reference) {}
    public record Proration(@NotBlank @Pattern(regexp="FULL_MONTH|ACTUAL_DAYS") String policy,@NotBlank @Size(max=1000) String reason) {}
    public record ServiceStop(@NotNull LocalDate endDate,@NotBlank @Size(max=1000) String reason) {}
    @Transactional public void stop(AuthenticatedUser p,long c,long service,ServiceStop r){var contract=access(p,c,true);mutable(c,r.endDate().withDayOfMonth(1));var rule=db.sql("SELECT * FROM contract_services WHERE id=:id AND contract_id=:contract FOR UPDATE").param("id",service).param("contract",c).query().listOfRows().stream().findFirst().orElseThrow(()->fail("SERVICE_INVALID","Dịch vụ không thuộc hợp đồng."));if(!r.endDate().isAfter(date(rule.get("effective_date"))))throw fail("SERVICE_DATES_INVALID","Ngày ngừng phải sau ngày bắt đầu.");db.sql("UPDATE contract_services SET end_date=:end,status='STOPPED' WHERE id=:id").param("end",r.endDate()).param("id",service).update();audit(contract,p,"SERVICE_STOPPED",rule+"; "+r);}
    public record Automation(boolean enabled,boolean autoIssue,@Min(1) @Max(28) int generationDay,
        @Min(1) @Max(28) int issueDay,@Min(1) @Max(28) int cutoffDay,@Min(1) @Max(28) int dueDay,
        @Min(-1) @Max(0) int periodOffset,@NotBlank @Size(max=1000) String reason) {}
    public record Charge(String type,String name,String description,BigDecimal quantity,String unit,BigDecimal price,BigDecimal amount,String source,Long sourceId) {}
    public record Plan(List<Charge> items,String content,String hash) {}
    public Plan finalPeriod(SaveInvoice r,Map<String,Object> c,LocalDate endExclusive,BigDecimal electricity,BigDecimal water){LocalDate period=LocalDate.parse(r.billingPeriod()+"-01");Map<String,Object> utility=new HashMap<>();utility.put("id",0L);utility.put("version",0L);utility.put("reading_status","CONFIRMED");for(var policy:policies(r.contractId()))if("METER".equals(policy.get("calculation_method"))){String type=policy.get("code").toString(),prefix="ELECTRICITY".equals(type)?"electricity":"water";meter(c,type);BigDecimal start=previous(r.contractId(),period,type),end="ELECTRICITY".equals(type)?electricity:water;if(end==null)throw fail("METER_READING_REQUIRED","Thiếu chỉ số bàn giao thực tế.");BigDecimal used=consumption(c,period,type,start,end);utility.put(prefix+"_previous",start);utility.put(prefix+"_current",end);utility.put(prefix+"_consumption",used);utility.put(prefix+"_unit_price",price(r.contractId(),type,period,money(policy.get("unit_price"))));}return calculate(r,c,utility,endExclusive);}
    public void validateSettlement(long c,LocalDate period,BigDecimal electricity,BigDecimal water,boolean utilityCharge){var contract=contract(c);if(utilityCharge&&db.sql("SELECT COUNT(*) FROM invoices i JOIN invoice_items x ON x.invoice_id=i.id WHERE i.contract_id=:id AND i.billing_period=:period AND i.status NOT IN ('DRAFT','PENDING_REVIEW','CANCELLED') AND x.item_type IN ('ELECTRICITY','WATER') AND x.amount>0").param("id",c).param("period",period.withDayOfMonth(1)).query(Long.class).single()>0)throw fail("UTILITY_SETTLEMENT_RECONCILIATION_REQUIRED","Điện/nước kỳ này đã được lập hóa đơn; cần đối soát phần còn lại, không thu lại toàn kỳ khi quyết toán.");for(var policy:policies(c))if("METER".equals(policy.get("calculation_method"))){String type=policy.get("code").toString();var m=meter(contract,type);BigDecimal end="ELECTRICITY".equals(type)?electricity:water;if(end==null||end.compareTo(money(m.get("current_reading")))<0)throw fail("METER_READING_INVALID","Chỉ số bàn giao cuối không hợp lệ; phải có sự kiện thay đồng hồ.");}}
    @Transactional public void automation(AuthenticatedUser p,long c,Automation r){var contract=access(p,c,true);if(p.activeRole()!=RoleCode.OWNER)throw fail("BILLING_OWNER_REQUIRED","Chủ trọ cấu hình tự động phát hành.");db.sql("INSERT INTO billing_settings(owner_id,auto_generate_invoices,invoice_generation_day,default_due_day,auto_issue_invoices,auto_issue_day,meter_cutoff_day,billing_period_offset,updated_by) VALUES(:owner,:enabled,:generation,:due,:issue,:issueDay,:cutoff,:offset,:actor) ON DUPLICATE KEY UPDATE auto_generate_invoices=:enabled,invoice_generation_day=:generation,default_due_day=:due,auto_issue_invoices=:issue,auto_issue_day=:issueDay,meter_cutoff_day=:cutoff,billing_period_offset=:offset,updated_by=:actor").param("owner",contract.get("owner_id")).param("enabled",r.enabled()).param("generation",r.generationDay()).param("due",r.dueDay()).param("issue",r.autoIssue()).param("issueDay",r.issueDay()).param("cutoff",r.cutoffDay()).param("offset",r.periodOffset()).param("actor",p.id()).update();audit(contract,p,"AUTOMATION",r.toString());}
    private final JdbcClient db; private final RoomLifecycleGuard rooms;
    public MonthlyBillingService(JdbcClient db){this.db=db;this.rooms=new RoomLifecycleGuard(db);}
    public static AuthException fail(String code,String message){return new AuthException(HttpStatus.CONFLICT,code,message);}
    public static BigDecimal money(Object x){return x==null?BigDecimal.ZERO:new BigDecimal(x.toString());}
    public static long id(Map<String,Object> x,String key){return ((Number)x.get(key)).longValue();}
    public static LocalDate date(Object x){if(x instanceof LocalDate d)return d;if(x instanceof LocalDateTime d)return d.toLocalDate();if(x instanceof java.sql.Timestamp d)return d.toLocalDateTime().toLocalDate();return ((java.sql.Date)x).toLocalDate();}
    public static String hash(String s){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(s.getBytes(StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException(e);}}
    private List<Map<String,Object>> rows(String sql,long id){return db.sql(sql).param("id",id).query().listOfRows();}
    private Map<String,Object> contract(long contract){return rows("SELECT c.*,r.property_id,p.owner_id FROM contracts c JOIN rooms r ON r.id=c.room_id JOIN properties p ON p.id=r.property_id WHERE c.id=:id",contract).stream().findFirst().orElseThrow(()->fail("CONTRACT_NOT_FOUND","Không tìm thấy hợp đồng."));}
    private Map<String,Object> access(AuthenticatedUser p,long contract,boolean write){rooms.lockContract(contract);var c=contract(contract);
        if(p==null)throw fail("BILLING_ACCESS_DENIED","Không có quyền.");
        if(p.activeRole()==RoleCode.OWNER||p.activeRole()==RoleCode.MANAGER){rooms.access(p,id(c,"property_id"));if(p.activeRole()==RoleCode.MANAGER)rooms.capability(p,id(c,"property_id"),write?com.thangit.boardinghouse.security.PropertyAuthorization.Capability.FINANCE_WRITE:com.thangit.boardinghouse.security.PropertyAuthorization.Capability.FINANCE_READ);}
        else if(!write&&p.activeRole()==RoleCode.ACCOUNTANT&&db.sql("SELECT COUNT(*) FROM accountant_property_assignments WHERE accountant_id=:user AND property_id=:property").param("user",p.id()).param("property",c.get("property_id")).query(Long.class).single()>0){}
        else throw new AuthException(HttpStatus.FORBIDDEN,"BILLING_ACCESS_DENIED","Không có quyền ghi điện nước/cấu hình hợp đồng này.");return c;}
    private void month(LocalDate period){if(period.getDayOfMonth()!=1)throw fail("BILLING_PERIOD_INVALID","Kỳ phải là ngày đầu tháng.");}
    private void open(long property,LocalDate period){if(db.sql("SELECT COUNT(*) FROM accounting_periods WHERE property_id=:id AND :date BETWEEN start_date AND end_date AND status='CLOSED'").param("id",property).param("date",period).query(Long.class).single()>0)throw fail("ACCOUNTING_PERIOD_CLOSED","Kỳ kế toán đã khóa.");}
    private void mutable(long contract,LocalDate period){month(period);open(id(contract(contract),"property_id"),period);
        if(db.sql("SELECT COUNT(*) FROM invoices WHERE contract_id=:id AND billing_period>=:period AND status NOT IN ('DRAFT','PENDING_REVIEW','CANCELLED')").param("id",contract).param("period",period).query(Long.class).single()>0)throw fail("BILLING_SOURCE_LOCKED","Đã có hóa đơn phát hành; phải điều chỉnh có chứng từ, không sửa nguồn tính tiền.");}
    public Map<String,Object> reading(long contract,LocalDate period){return db.sql("SELECT * FROM utility_readings WHERE contract_id=:id AND billing_period=:period FOR UPDATE").param("id",contract).param("period",period).query().listOfRows().stream().findFirst().orElse(null);}
    private Map<String,Object> baseline(long contract,String type){return db.sql("SELECT * FROM contract_meter_baselines WHERE contract_id=:id AND meter_type=:type").param("id",contract).param("type",type).query().listOfRows().stream().findFirst().orElseThrow(()->fail("METER_BASELINE_REQUIRED","Thiếu mốc bàn giao "+type+" đã xác nhận."));}
    private Map<String,Object> meter(Map<String,Object> c,String type){return db.sql("SELECT * FROM utility_meters WHERE room_id=:id AND meter_type=:type AND status='ACTIVE' FOR UPDATE").param("id",c.get("room_id")).param("type",type).query().listOfRows().stream().findFirst().orElseThrow(()->fail("ROOM_METER_REQUIRED","Thiếu đồng hồ đang hoạt động "+type));}
    private List<Map<String,Object>> policies(long c){return rows("SELECT * FROM contract_utility_rates WHERE contract_id=:id ORDER BY code",c);}
    public BigDecimal price(long c,String code,LocalDate period,BigDecimal fallback){return db.sql("SELECT unit_price FROM billing_rate_versions WHERE contract_id=:id AND code=:code AND effective_date<=:period ORDER BY effective_date DESC LIMIT 1").param("id",c).param("code",code).param("period",period).query(BigDecimal.class).optional().orElse(fallback);}
    private BigDecimal previous(long contract,LocalDate period,String type){var b=baseline(contract,type);if(period.isBefore(date(b.get("recorded_at")).withDayOfMonth(1)))throw fail("READING_BEFORE_HANDOVER","Kỳ ghi trước thời điểm bàn giao.");String prefix=type.equals("ELECTRICITY")?"electricity":"water";
        var prev=reading(contract,period.minusMonths(1));
        if(period.isAfter(date(b.get("recorded_at")).withDayOfMonth(1))&&(prev==null||!"CONFIRMED".equals(prev.get("reading_status"))||prev.get(prefix+"_current")==null))throw fail("PREVIOUS_READING_REQUIRED","Thiếu kỳ trước đã chốt; không tự điền mức sử dụng bằng 0.");
        return prev==null?money(b.get("reading")):money(prev.get(prefix+"_current"));}
    private BigDecimal consumption(Map<String,Object> c,LocalDate period,String type,BigDecimal start,BigDecimal end){
        BigDecimal total=BigDecimal.ZERO,cursor=start;var b=baseline(id(c,"id"),type);
        var events=db.sql("SELECT * FROM utility_meter_events WHERE meter_id=:meter AND occurred_at>:at ORDER BY occurred_at,id").param("meter",b.get("meter_id")).param("at",b.get("recorded_at")).query().listOfRows();
        for(var event:events){if(event.get("billing_period")==null||event.get("removed_reading")==null||event.get("contract_id")==null)throw fail("METER_ADJUSTMENT_REVIEW_REQUIRED","Sự kiện đồng hồ cũ thiếu đoạn sử dụng; cần đối soát có chứng từ.");if(id(event,"contract_id")!=id(c,"id"))continue;LocalDate ep=date(event.get("billing_period"));if(!ep.equals(period))continue;BigDecimal removed=money(event.get("removed_reading"));if(removed.compareTo(cursor)<0)throw fail("METER_READING_INVALID","Chỉ số tháo thấp hơn đầu đoạn.");total=total.add(removed.subtract(cursor));cursor=money(event.get("new_reading"));}
        if(end==null||end.compareTo(cursor)<0)throw fail("METER_READING_INVALID","Chỉ số cuối thấp hơn đầu đoạn hoặc chưa có biên bản thay đồng hồ.");return total.add(end.subtract(cursor));}
    @Transactional public Map<String,Object> detail(AuthenticatedUser p,long c,LocalDate period){var contract=access(p,c,false);month(period);var out=new LinkedHashMap<String,Object>();out.put("contract",contract);out.put("reading",reading(c,period));out.put("rates",policies(c));out.put("services",rows("SELECT * FROM contract_services WHERE contract_id=:id ORDER BY id",c));out.put("rateHistory",rows("SELECT * FROM billing_rate_versions WHERE contract_id=:id ORDER BY effective_date,id",c));out.put("meters",rows("SELECT * FROM utility_meters WHERE room_id=:id ORDER BY meter_type",id(contract,"room_id")));out.put("runs",rows("SELECT * FROM billing_run_results WHERE contract_id=:id ORDER BY billing_period DESC LIMIT 12",c));out.put("automation",rows("SELECT b.* FROM billing_settings b WHERE owner_id=:id",id(contract,"owner_id")));out.put("revisions",rows("SELECT v.* FROM utility_reading_revisions v JOIN utility_readings u ON u.id=v.reading_id WHERE u.contract_id=:id ORDER BY v.id DESC LIMIT 24",c));
        var starts=new LinkedHashMap<String,Object>();for(var policy:policies(c))if("METER".equals(policy.get("calculation_method")))try{starts.put(policy.get("code").toString(),previous(c,period,policy.get("code").toString()));}catch(AuthException e){starts.put(policy.get("code").toString(),e.getMessage());}out.put("previous",starts);return out;}
    @Transactional public Map<String,Object> record(AuthenticatedUser p,long c,Reading r){var contract=access(p,c,true);mutable(c,r.period());if(r.period().isAfter(LocalDate.now(ZoneId.of("Asia/Ho_Chi_Minh")).withDayOfMonth(1)))throw fail("READING_FUTURE_PERIOD","Không chốt tiêu thụ cho kỳ tương lai.");if(!Set.of("ACTIVE","EXPIRING","TERMINATION_REQUESTED","SETTLING","EXPIRED").contains(contract.get("status")))throw fail("READING_CONTRACT_INVALID","Hợp đồng chưa nhận phòng hoặc đã đóng.");
        var existing=reading(c,r.period());if((existing==null?0:id(existing,"version"))!=r.version())throw fail("READING_VERSION_CONFLICT","Chỉ số đã được người khác cập nhật.");
        if(db.sql("SELECT COUNT(*) FROM utility_readings WHERE contract_id=:id AND billing_period>:period").param("id",c).param("period",r.period()).query(Long.class).single()>0)throw fail("READING_CHAIN_LOCKED","Đã có kỳ sau; cần đối soát toàn chuỗi trước khi sửa.");
        var values=new HashMap<String,Object>();var warnings=new ArrayList<String>();
        for(var policy:policies(c)){String type=policy.get("code").toString(),prefix=type.equals("ELECTRICITY")?"electricity":"water";if(!"METER".equals(policy.get("calculation_method")))continue;meter(contract,type);BigDecimal end=type.equals("ELECTRICITY")?r.electricity():r.water();if(end==null||end.signum()<0)throw fail("METER_READING_REQUIRED","Thiếu chỉ số cuối "+type);BigDecimal start=previous(c,r.period(),type),used=consumption(contract,r.period(),type,start,end);BigDecimal unit=price(c,type,r.period(),money(policy.get("unit_price")));values.put(prefix+"_previous",start);values.put(prefix+"_current",end);values.put(prefix+"_consumption",used);values.put(prefix+"_unit_price",unit);values.put(prefix+"_amount",used.multiply(unit).setScale(2,RoundingMode.HALF_UP));var prev=reading(c,r.period().minusMonths(1));if(used.signum()==0)warnings.add(type+": không phát sinh sử dụng");if(prev!=null&&prev.get(prefix+"_consumption")!=null&&money(prev.get(prefix+"_consumption")).signum()>0&&used.compareTo(money(prev.get(prefix+"_consumption")).multiply(new BigDecimal("3")))>0)warnings.add(type+": tiêu thụ hơn 3 lần kỳ trước");}
        if(values.isEmpty())throw fail("METER_POLICY_NOT_REQUIRED","Hợp đồng không tính theo đồng hồ riêng.");if(!warnings.isEmpty()&&!r.confirmWarnings())throw fail("READING_WARNING_REVIEW",String.join("; ",warnings)+". Kiểm tra chứng từ và xác nhận kèm lý do.");
        if(existing==null){db.sql("INSERT INTO utility_readings(contract_id,billing_period) VALUES(:id,:period)").param("id",c).param("period",r.period()).update();existing=reading(c,r.period());}
        StringBuilder sql=new StringBuilder("UPDATE utility_readings SET version=version+1,reading_status='CONFIRMED',recorded_by=:actor,recorded_at=NOW(6),evidence_reference=:reference,verification_reason=:reason");for(String key:new TreeSet<>(values.keySet()))sql.append(',').append(key).append("=:").append(key);sql.append(" WHERE id=:id");db.sql(sql.toString()).params(values).param("actor",p.id()).param("reference",r.reference()).param("reason",r.reason()).param("id",existing.get("id")).update();var saved=reading(c,r.period());db.sql("INSERT INTO utility_reading_revisions(reading_id,version,content,actor_id,reason) VALUES(:id,:version,:content,:actor,:reason)").param("id",saved.get("id")).param("version",saved.get("version")).param("content",new TreeMap<>(saved).toString()).param("actor",p.id()).param("reason",r.reason()+"; "+String.join("; ",warnings)).update();return saved;}
    @Transactional public void replace(AuthenticatedUser p,long c,Replacement r){var contract=access(p,c,true);mutable(c,r.period());if(r.period().isAfter(LocalDate.now(ZoneId.of("Asia/Ho_Chi_Minh")).withDayOfMonth(1)))throw fail("READING_FUTURE_PERIOD","Chưa đến kỳ thay đồng hồ.");var existing=reading(c,r.period());if(existing!=null&&id(existing,"version")!=r.version())throw fail("READING_VERSION_CONFLICT","Version chỉ số đã thay đổi.");if(db.sql("SELECT COUNT(*) FROM utility_readings WHERE contract_id=:id AND billing_period>:period").param("id",c).param("period",r.period()).query(Long.class).single()>0)throw fail("READING_CHAIN_LOCKED","Đã có kỳ sau.");
        var m=meter(contract,r.type());BigDecimal start=previous(c,r.period(),r.type());consumption(contract,r.period(),r.type(),start,r.removedReading());
        db.sql("INSERT INTO utility_meter_events(meter_id,old_code,new_code,old_reading,new_reading,reason,evidence_reference,actor_id,contract_id,billing_period,removed_reading) VALUES(:meter,:old,:new,:oldReading,:newReading,:reason,:reference,:actor,:contract,:period,:removed)").param("meter",m.get("id")).param("old",m.get("meter_code")).param("new",r.code()).param("oldReading",m.get("current_reading")).param("newReading",r.installedReading()).param("reason",r.reason()).param("reference",r.reference()).param("actor",p.id()).param("contract",c).param("period",r.period()).param("removed",r.removedReading()).update();db.sql("UPDATE utility_meters SET meter_code=:code,current_reading=:reading WHERE id=:id").param("code",r.code()).param("reading",r.installedReading()).param("id",m.get("id")).update();if(existing!=null)db.sql("UPDATE utility_readings SET reading_status='NEEDS_REVIEW',version=version+1 WHERE id=:id").param("id",existing.get("id")).update();audit(contract,p,"METER_REPLACED",r.toString());}
    @Transactional public void rate(AuthenticatedUser p,long c,Rate r){var contract=access(p,c,true);mutable(c,r.effectiveDate());if(r.effectiveDate().isBefore(LocalDate.now(ZoneId.of("Asia/Ho_Chi_Minh")).withDayOfMonth(1)))throw fail("RATE_HISTORY_REVIEW_REQUIRED","Không tự sửa giá kỳ quá khứ.");if(!"RENT".equals(r.code())&&policies(c).stream().noneMatch(x->r.code().equals(x.get("code"))))throw fail("UTILITY_POLICY_REQUIRED","Chưa có chính sách hợp đồng tương ứng.");db.sql("INSERT INTO billing_rate_versions(contract_id,code,effective_date,unit_price,reference,reason,actor_id) VALUES(:id,:code,:date,:price,:reference,:reason,:actor)").param("id",c).param("code",r.code()).param("date",r.effectiveDate()).param("price",r.unitPrice()).param("reference",r.reference()).param("reason",r.reason()).param("actor",p.id()).update();audit(contract,p,"RATE_VERSION",r.toString());}
    @Transactional public void proration(AuthenticatedUser p,long c,Proration r){var contract=access(p,c,true);if(db.sql("SELECT COUNT(*) FROM invoices WHERE contract_id=:id AND status NOT IN ('DRAFT','PENDING_REVIEW','CANCELLED')").param("id",c).query(Long.class).single()>0)throw fail("PRORATION_ALREADY_BILLED","Đã phát hành; phải xử lý phụ lục/quyết toán trước khi đổi chính sách.");db.sql("UPDATE contracts SET rent_proration=:policy WHERE id=:id").param("policy",r.policy()).param("id",c).update();audit(contract,p,"PRORATION",r.toString());}
    @Transactional public long service(AuthenticatedUser p,long c,ServiceRule r){var contract=access(p,c,true);mutable(c,r.effectiveDate().withDayOfMonth(1));if(r.endDate()!=null&&!r.endDate().isAfter(r.effectiveDate()))throw fail("SERVICE_DATES_INVALID","Ngày ngừng phải sau ngày hiệu lực.");if(db.sql("SELECT COUNT(*) FROM contract_services WHERE contract_id=:id AND code=:code AND effective_date<COALESCE(:end,'9999-12-31') AND (end_date IS NULL OR end_date>:start)").param("id",c).param("code",r.code()).param("end",r.endDate()).param("start",r.effectiveDate()).query(Long.class).single()>0)throw fail("SERVICE_OVERLAP","Mã dịch vụ đã áp dụng trong khoảng này.");if("QUANTITY".equals(r.method())&&r.quantity()==null)throw fail("SERVICE_QUANTITY_REQUIRED","Phải khai số lượng theo thỏa thuận.");var kh=new org.springframework.jdbc.support.GeneratedKeyHolder();db.sql("INSERT INTO contract_services(contract_id,code,name,calculation_method,unit_price,effective_date,end_date,quantity,unit,prorate) VALUES(:id,:code,:name,:method,:price,:start,:end,:qty,:unit,:prorate)").param("id",c).param("code",r.code()).param("name",r.name()).param("method",r.method()).param("price",r.unitPrice()).param("start",r.effectiveDate()).param("end",r.endDate()).param("qty",r.quantity()).param("unit",r.unit()).param("prorate",r.prorate()).update(kh,"id");audit(contract,p,"SERVICE_AGREED",r.toString());return kh.getKey().longValue();}
    @Transactional public void usage(AuthenticatedUser p,long c,long service,Usage r){var contract=access(p,c,true);mutable(c,r.period());if(db.sql("SELECT COUNT(*) FROM contract_services WHERE id=:service AND contract_id=:id AND calculation_method='USAGE'").param("service",service).param("id",c).query(Long.class).single()!=1)throw fail("SERVICE_INVALID","Dịch vụ không thuộc hợp đồng hoặc không tính theo sử dụng.");db.sql("INSERT INTO service_period_usage(service_id,billing_period,quantity,actor_id,reference) VALUES(:service,:period,:qty,:actor,:reference)").param("service",service).param("period",r.period()).param("qty",r.quantity()).param("actor",p.id()).param("reference",r.reference()).update();audit(contract,p,"SERVICE_USAGE",r.toString());}
    private void audit(Map<String,Object> c,AuthenticatedUser p,String kind,String content){db.sql("INSERT INTO billing_configuration_history(contract_id,owner_id,actor_id,content,reason) VALUES(:contract,:owner,:actor,:content,:reason)").param("contract",c.get("id")).param("owner",c.get("owner_id")).param("actor",p.id()).param("content",content).param("reason",kind).update();}
    public static BigDecimal rent(BigDecimal price,LocalDate month,LocalDate start,LocalDate end,String policy){long days=ChronoUnit.DAYS.between(start,end);if(days<=0)throw fail("INVOICE_PERIOD_INVALID","Không có ngày phát sinh nghĩa vụ.");if("FULL_MONTH".equals(policy))return price;if(!"ACTUAL_DAYS".equals(policy))throw fail("RENT_POLICY_UNSUPPORTED","Chưa có quy tắc phân bổ chu kỳ này.");return price.multiply(BigDecimal.valueOf(days)).divide(BigDecimal.valueOf(month.lengthOfMonth()),2,RoundingMode.HALF_UP);}
    public BigDecimal rentForPeriod(long contract,BigDecimal fallback,LocalDate month,LocalDate start,LocalDate end,String policy){
        if(!end.isAfter(start))return BigDecimal.ZERO;
        var versions=db.sql("SELECT effective_date,unit_price FROM billing_rate_versions WHERE contract_id=:id AND code='RENT' AND effective_date>:start AND effective_date<:end ORDER BY effective_date,id").param("id",contract).param("start",start).param("end",end).query().listOfRows();
        if("FULL_MONTH".equals(policy)){if(!versions.isEmpty())throw fail("RENT_PRORATION_AGREEMENT_REQUIRED","Giá đổi giữa kỳ cần chính sách phân bổ theo ngày đã thỏa thuận.");return price(contract,"RENT",start,fallback);}
        if(!"ACTUAL_DAYS".equals(policy))throw fail("RENT_POLICY_UNSUPPORTED","Chưa có quy tắc phân bổ chu kỳ này.");
        BigDecimal total=BigDecimal.ZERO,unit=price(contract,"RENT",start,fallback);LocalDate cursor=start;
        for(var v:versions){LocalDate stop=date(v.get("effective_date"));total=total.add(unit.multiply(BigDecimal.valueOf(ChronoUnit.DAYS.between(cursor,stop))));cursor=stop;unit=money(v.get("unit_price"));}
        total=total.add(unit.multiply(BigDecimal.valueOf(ChronoUnit.DAYS.between(cursor,end))));return total.divide(BigDecimal.valueOf(month.lengthOfMonth()),2,RoundingMode.HALF_UP);
    }
    public BigDecimal residentDays(long contract,LocalDate start,LocalDate end){
        var periods=db.sql("SELECT tenant_profile_id,move_in_date,move_out_date FROM tenant_residences WHERE contract_id=:id AND move_in_date<:end AND (move_out_date IS NULL OR move_out_date>:start) ORDER BY tenant_profile_id,move_in_date").param("id",contract).param("start",start).param("end",end).query().listOfRows();
        if(periods.isEmpty())throw fail("RESIDENCE_RECONCILIATION_REQUIRED","Thiếu lịch sử cư trú để tính phí theo người.");
        long count=0;Map<Long,LocalDate> previous=new HashMap<>();for(var row:periods){long person=id(row,"tenant_profile_id");LocalDate s=date(row.get("move_in_date"));if(s.isBefore(start))s=start;LocalDate e=row.get("move_out_date")==null?end:date(row.get("move_out_date"));if(e.isAfter(end))e=end;if(previous.containsKey(person)&&s.isBefore(previous.get(person)))throw fail("RESIDENCE_OVERLAP_REVIEW_REQUIRED","Lịch sử cư trú trùng cần đối soát.");previous.put(person,e);count+=ChronoUnit.DAYS.between(s,e);}return BigDecimal.valueOf(count);
    }
    public Plan calculate(SaveInvoice r,Map<String,Object> c){return calculate(r,c,null,null);}
    private Plan calculate(SaveInvoice r,Map<String,Object> c,Map<String,Object> utilityOverride,LocalDate endOverride){if(endOverride==null&&db.sql("SELECT COUNT(*) FROM rental_checkouts WHERE contract_id=:id AND settlement_applied_at IS NOT NULL").param("id",r.contractId()).query(Long.class).single()>0)throw fail("CONTRACT_SETTLEMENT_FINALIZED","Checkout statement already applied; use an audited adjustment");LocalDate period=LocalDate.parse(r.billingPeriod()+"-01");month(period);open(id(c,"property_id"),period);if(!r.periodStartDate().withDayOfMonth(1).equals(period)||!r.periodEndDate().withDayOfMonth(1).equals(period)||r.periodEndDate().isBefore(r.periodStartDate()))throw fail("INVOICE_PERIOD_INVALID","Ngày kỳ phải nằm trong tháng đã chọn.");if(!Set.of("ACTIVE","EXPIRING","TERMINATION_REQUESTED","SETTLING","EXPIRED","PENDING_CONFIRMATION").contains(c.get("status")))throw fail("INVOICE_CONTRACT_INVALID","Hợp đồng không đủ điều kiện tính tiền.");
        LocalDate start=date(c.get("start_date")),end=endOverride==null?date(c.get("end_date")):endOverride;if("PENDING_CONFIRMATION".equals(c.get("status"))&&(!Boolean.TRUE.equals(c.get("initial_payment_required"))||!period.equals(start.withDayOfMonth(1))))throw fail("INITIAL_INVOICE_NOT_REQUIRED","Hợp đồng chưa nhận phòng chỉ được lập khoản đầu kỳ đã thỏa thuận.");
        if(period.isAfter(LocalDate.now(ZoneId.of("Asia/Ho_Chi_Minh")).withDayOfMonth(1))&&!"PENDING_CONFIRMATION".equals(c.get("status")))throw fail("INVOICE_FUTURE_PERIOD","Chưa phát sinh nghĩa vụ kỳ tương lai.");
        var actual=rows("SELECT actual_checkin_at FROM rental_checkins WHERE contract_id=:id AND status='COMPLETED'",r.contractId());if(!actual.isEmpty()&&date(actual.get(0).get("actual_checkin_at")).isAfter(start))start=date(actual.get(0).get("actual_checkin_at"));
        var checkout=rows("SELECT actual_checkout_at FROM rental_checkouts WHERE contract_id=:id AND actual_checkout_at IS NOT NULL",r.contractId());if(endOverride==null&&!checkout.isEmpty()&&date(checkout.get(0).get("actual_checkout_at")).isBefore(end))end=date(checkout.get(0).get("actual_checkout_at"));
        start=start.isAfter(r.periodStartDate())?start:r.periodStartDate();LocalDate requestEnd=r.periodEndDate().plusDays(1);end=end.isBefore(requestEnd)?end:requestEnd;
        if(c.get("monthly_rent")==null)throw fail("CONTRACT_RENT_RECONCILIATION_REQUIRED","Thiếu giá thuê đã chốt.");BigDecimal rentPrice=price(r.contractId(),"RENT",period,money(c.get("monthly_rent"))),rent=!end.isAfter(start)&&endOverride!=null?("FULL_MONTH".equals(c.get("rent_proration"))?rentPrice:BigDecimal.ZERO):rentForPeriod(r.contractId(),rentPrice,period,start,end,Objects.toString(c.get("rent_proration"),"FULL_MONTH"));
        var items=new ArrayList<Charge>();items.add(new Charge("ROOM_RENT","Tiền thuê phòng",start+" → "+end+" (không tính ngày cuối); "+c.get("rent_proration"),"ACTUAL_DAYS".equals(c.get("rent_proration"))?BigDecimal.valueOf(ChronoUnit.DAYS.between(start,end)):BigDecimal.ONE,"ACTUAL_DAYS".equals(c.get("rent_proration"))?"ng\u00e0y":"tháng","ACTUAL_DAYS".equals(c.get("rent_proration"))?(end.isAfter(start)?rent.divide(BigDecimal.valueOf(ChronoUnit.DAYS.between(start,end)),8,RoundingMode.HALF_UP):BigDecimal.ZERO):rentPrice,rent,"CONTRACT",r.contractId()));StringBuilder provenance=new StringBuilder(start+"|"+end+"|"+c.get("rent_proration"));
        provenance.append("|rentPrices=").append(db.sql("SELECT effective_date,unit_price,reference FROM billing_rate_versions WHERE contract_id=:id AND code='RENT' AND effective_date<:end ORDER BY effective_date,id").param("id",r.contractId()).param("end",end).query().listOfRows());
        var ur=utilityOverride==null?reading(r.contractId(),period):utilityOverride;for(var policy:policies(r.contractId())){String type=policy.get("code").toString();if(!Set.of("METER","FIXED").contains(policy.get("calculation_method")))throw fail("UTILITY_METHOD_UNSUPPORTED","Biểu giá này cần quy tắc phân bổ đã xác minh.");if(date(policy.get("effective_date")).isAfter(period.plusMonths(1).minusDays(1)))throw fail("UTILITY_POLICY_NOT_EFFECTIVE","Đơn giá chưa có hiệu lực trong kỳ.");if("FIXED".equals(policy.get("calculation_method"))){BigDecimal price=price(r.contractId(),type,period,money(policy.get("unit_price")));items.add(new Charge(type,policy.get("name").toString(),"Phí cố định theo hợp đồng",BigDecimal.ONE,policy.get("unit").toString(),price,price,"CONTRACT_UTILITY_RATE",id(policy,"id")));continue;}
            if("PENDING_CONFIRMATION".equals(c.get("status"))&&ur==null)continue;
            if(ur==null||!"CONFIRMED".equals(ur.get("reading_status")))throw fail("METER_READING_REQUIRED","Thiếu chỉ số đã chốt; không phát hành với mức dùng giả bằng 0.");String prefix=type.equals("ELECTRICITY")?"electricity":"water";if(ur.get(prefix+"_consumption")==null)throw fail("METER_SEGMENTS_REQUIRED","Chỉ số cũ chưa có chứng cứ tính theo đoạn.");BigDecimal qty=money(ur.get(prefix+"_consumption")),price=price(r.contractId(),type,period,money(policy.get("unit_price")));if(price.compareTo(money(ur.get(prefix+"_unit_price")))!=0)throw fail("READING_RATE_STALE","Giá đã thay đổi; cần kiểm tra và chốt lại chỉ số trước lập hóa đơn.");items.add(new Charge(type,policy.get("name").toString(),ur.get(prefix+"_previous")+" → "+ur.get(prefix+"_current")+"; xem biên bản thay đồng hồ nếu có",qty,policy.get("unit").toString(),price,qty.multiply(price).setScale(2,RoundingMode.HALF_UP),"UTILITY_READING",id(ur,"id")));provenance.append('|').append(ur.get("version"));}
        for(var service:rows("SELECT * FROM contract_services WHERE contract_id=:id ORDER BY id",r.contractId())){if(!"MONTHLY".equals(service.get("billing_cycle")))throw fail("SERVICE_CYCLE_REVIEW_REQUIRED","Chu kỳ dịch vụ cần quy tắc phân bổ rõ ràng.");LocalDate s=date(service.get("effective_date")),e=service.get("end_date")==null?end:date(service.get("end_date"));s=s.isAfter(start)?s:start;e=e.isBefore(end)?e:end;if(!e.isAfter(s))continue;if(!"ACTIVE".equals(service.get("status"))&&service.get("end_date")==null)throw fail("SERVICE_END_DATE_REQUIRED","Dịch vụ ngừng cần ngày kết thúc để phân bổ chính xác.");String method=service.get("calculation_method").toString();BigDecimal qty=BigDecimal.ONE;
            switch(method){case "FIXED" -> {}case "PER_PERSON" -> qty=Boolean.TRUE.equals(service.get("prorate"))?residentDays(r.contractId(),s,e).divide(BigDecimal.valueOf(ChronoUnit.DAYS.between(s,e)),8,RoundingMode.HALF_UP):db.sql("SELECT GREATEST(1,COUNT(DISTINCT tenant_profile_id)) FROM tenant_residences WHERE contract_id=:id AND move_in_date<=:end AND (move_out_date IS NULL OR move_out_date>:end)").param("id",r.contractId()).param("end",e.minusDays(1)).query(BigDecimal.class).single();case "QUANTITY" -> {if(service.get("quantity")==null)throw fail("SERVICE_QUANTITY_REQUIRED","Thiếu số lượng dịch vụ.");qty=money(service.get("quantity"));}case "USAGE" -> qty=db.sql("SELECT quantity FROM service_period_usage WHERE service_id=:id AND billing_period=:period").param("id",service.get("id")).param("period",period).query(BigDecimal.class).optional().orElseThrow(()->fail("SERVICE_USAGE_REQUIRED","Thiếu mức sử dụng dịch vụ."));case "ONCE" -> {if(!date(service.get("effective_date")).withDayOfMonth(1).equals(period))continue;}default -> throw fail("SERVICE_METHOD_UNSUPPORTED","Chưa hỗ trợ cách tính dịch vụ này.");}
            BigDecimal price=money(service.get("unit_price")),amount=qty.multiply(price);if(Boolean.TRUE.equals(service.get("prorate")))amount=amount.multiply(BigDecimal.valueOf(ChronoUnit.DAYS.between(s,e))).divide(BigDecimal.valueOf(period.lengthOfMonth()),2,RoundingMode.HALF_UP);items.add(new Charge("SERVICE",service.get("name").toString(),s+" → "+e+"; "+method,qty,service.get("unit").toString(),price,amount.setScale(2,RoundingMode.HALF_UP),"CONTRACT_SERVICE",id(service,"id")));}
        if(r.additionalItems()!=null)for(var item:r.additionalItems())items.add(new Charge("SURCHARGE",item.name(),item.reason(),item.quantity(),item.unit(),item.unitPrice(),item.quantity().multiply(item.unitPrice()).setScale(2,RoundingMode.HALF_UP),"MANUAL",null));
        if(r.discountAmount()!=null&&r.discountAmount().signum()>0&&(r.note()==null||r.note().isBlank()))throw fail("DISCOUNT_REASON_REQUIRED","Giảm giá phải có lý do.");String content=provenance+"\n"+items.stream().map(x->x.type()+"|"+x.name()+"|"+x.description()+"|"+x.quantity().stripTrailingZeros().toPlainString()+"|"+x.unit()+"|"+x.price().stripTrailingZeros().toPlainString()+"|"+x.amount().stripTrailingZeros().toPlainString()+"|"+x.source()+"|"+x.sourceId()).toList()+"\ndiscount="+money(r.discountAmount()).stripTrailingZeros()+"; reason="+Objects.toString(r.note(),"");return new Plan(List.copyOf(items),content,hash(content));}
}
